<section class="card"><h2>Account directory — all staff</h2><p>Edit an existing person to update role, department or Adjunct classification. Disable temporarily unavailable staff; enable the same entry when they return.</p>
<form method="get" class="filters"><input type="hidden" name="page" value="admin"><label class="grow">Search name or email<input name="staff_search" value="<?=e($_GET['staff_search']??'')?>"></label><label>Department<select name="staff_department"><option value="">All departments</option><?php foreach(accountDepartments()as $dept):?><option <?=($_GET['staff_department']??'')===$dept?'selected':''?>><?=e($dept)?></option><?php endforeach;?></select></label><label>Status<select name="staff_status"><option value="">All statuses</option><?php foreach(['Active','Inactive']as $status):?><option <?=($_GET['staff_status']??'')===$status?'selected':''?>><?=$status?></option><?php endforeach;?></select></label><button>Search staff</button><a class="button secondary" href="?page=admin">Clear</a></form>
<?php if(attReady()):?><form method="post" id="bulk-attendance" class="bulk-attendance"><?php csrf();?><input type="hidden" name="action" value="staff_attendance_bulk"><p>Select staff below, or select all active staff in the filtered list. These buttons change teaching attendance only.</p><div class="service-links"><button name="enabled" value="1">Enable attendance for selected</button><button class="secondary" name="enabled" value="0">Disable attendance for selected</button></div><output id="attendance-selection-count" aria-live="polite">0 selected</output></form><?php endif;?>
<div class="table-wrap"><table><thead><tr><th><?php if(attReady()):?><label class="check"><input type="checkbox" id="select-attendance-staff">Select all shown</label><?php endif;?></th><th>Name</th><th>Email</th><th>Role</th><th>Department</th><th>Staff type</th><th>Account status</th><th>Teaching attendance</th><th>Actions</th></tr></thead><tbody>
<?php $directory=filteredStaff($_GET);foreach($directory as $person):$profile=staffProfile((int)$person['id']);?><tr><td><?php if(attReady()):?><input type="checkbox" class="attendance-staff-choice" name="staff_ids[]" value="<?=$person['id']?>" form="bulk-attendance" aria-label="Select <?=e($person['name'])?>" <?=$person['active']?'':'disabled'?>><?php endif;?></td><td><?=e($person['name'])?></td><td><?=e($person['email'])?></td><td><?=e(strtoupper($person['role']))?></td><td><?=e($person['department'])?></td><td><?=e($profile['staff_type'])?></td><td><span class="badge <?=$person['active']?'good':''?>"><?=$person['active']?'Active':'Inactive'?></span><small><?=e($profile['status_reason'])?></small></td><td><?=teaching($person)?'Enabled':'Disabled'?></td><td><a href="?page=edit_user&id=<?=$person['id']?>">Edit</a><?php if((int)$person['id']!==(int)$user['id']):?><form method="post" data-confirm="<?=$person['active']?'Disable this staff entry? Existing records are retained.':'Enable this staff entry again?'?>"><?php csrf();?><input type="hidden" name="action" value="staff_status"><input type="hidden" name="id" value="<?=$person['id']?>"><input type="hidden" name="active" value="<?=$person['active']?'0':'1'?>"><input type="hidden" name="status_reason" value="<?=e($profile['status_reason'])?>"><button class="secondary"><?=$person['active']?'Disable':'Enable'?></button></form><?php else:?><small>Another administrator manages your status.</small><?php endif;?></td></tr><?php endforeach;?>
<?php if(!$directory):?><tr><td colspan="9">No staff match these filters.</td></tr><?php endif;?></tbody></table></div></section>
